import sys

mod = 998244353

def power(base, exp):
    result = 1
    while exp > 0:
        if exp & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return result

class Matrix:
    def __init__(self, m):
        self.mat = m

    def pow(self, x):
        res = Matrix([[1, 0], [0, 1]])
        base = Matrix([row[:] for row in self.mat])
        while x > 0:
            if x & 1:
                res = res.multiply(base)
            base = base.multiply(base)
            x >>= 1
        return res

    def multiply(self, m):
        r = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    r[i][j] += self.mat[i][k] * m.mat[k][j]
                r[i][j] %= mod
        return Matrix(r)

def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    m = int(data[1])
    L = int(data[2])
    R = int(data[3])

    if n % 2 == 1 and m % 2 == 1:
        print(power((R - L + 1) % mod, n * m))
    else:
        length = R - L + 1
        if length % 2 == 0:
            total = powMod(length % mod, n * m - 1)
            result = total * (length // 2) % mod
            print(result)
        else:
            half = length // 2
            identity = Matrix([[1, 0], [0, 1]])
            matrix = Matrix([[half, half + 1], [half + 1, half]])
            resultMatrix = matrix.pow(n * m)
            print(resultMatrix.mat[0][0])

def powMod(base, exp):
    result = 1
    while exp > 0:
        if exp & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return result

if __name__ == "__main__":
    main()

